import Link from 'next/link';import {requireVendor} from '@/lib/auth/vendor';import {fcfa,getVendorOrders,vendorStatusLabels} from '@/services/vendor-dashboard';
const filters=[['','Toutes'],['pending','Nouvelles'],['preparing','En préparation'],['ready','Prêtes'],['out_for_delivery','En livraison'],['done','Terminées'],['cancelled','Annulées']];
export default async function OrdersPage({searchParams}:{searchParams:Promise<{status?:string}>}){const[{status},context]=await Promise.all([searchParams,requireVendor()]);const rows=await getVendorOrders(context.restaurant!.id);const visible=rows.filter(row=>!status||status==='done'?status?['delivered','collected'].includes(row.status):true:status==='ready'?['ready','ready_for_pickup'].includes(row.status):row.status===status);return <><div className="vendor-page-head"><div><p className="section-kicker">Suivi</p><h1>Commandes</h1><p>Uniquement les commandes de {context.restaurant!.name}.</p></div></div><nav className="vendor-filters" aria-label="Filtrer les commandes">{filters.map(([key,label])=><Link key={key} href={key?`/vendor/orders?status=${key}`:'/vendor/orders'} className={(status??'')===key?'active':''}>{label}</Link>)}</nav><section className="vendor-card">{visible.length?<div className="vendor-order-list large">{visible.map(row=>{const order=row.order as unknown as Record<string,unknown>;return <Link href={`/vendor/orders/${row.id}`} key={row.id}><span><strong>{String(order.reference)}</strong><small>{new Intl.DateTimeFormat('fr-FR',{hour:'2-digit',minute:'2-digit'}).format(new Date(row.created_at))} · {String(order.customer_name)} · {String(order.fulfillment)==='pickup'?'Retrait':'Livraison'}</small></span><span><b>{fcfa(row.subtotal+row.delivery_fee)}</b><small className={`order-state ${row.status}`}>{vendorStatusLabels[row.status]}</small></span></Link>})}</div>:<div className="vendor-empty"><strong>Aucune commande pour le moment.</strong><p>Changez de filtre ou revenez un peu plus tard.</p></div>}</section></>}
